class Solution:
    def numDistinctIslands2(self, grid):
        m, n = len(grid), len(grid[0])
        seen = [[False]*n for _ in range(m)]

        def collect(sr, sc):
            stack, cells = [(sr, sc)], []
            seen[sr][sc] = True
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] and not seen[nr][nc]:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            return cells

        def norm(cells):
            mr = min(r for r, c in cells)
            mc = min(c for r, c in cells)
            return tuple(sorted((r-mr, c-mc) for r, c in cells))

        def transform(cells, t):
            out = []
            for r, c in cells:
                if t == 0: out.append((r, c))
                elif t == 1: out.append((-r, c))
                elif t == 2: out.append((r, -c))
                elif t == 3: out.append((-r, -c))
                elif t == 4: out.append((c, r))
                elif t == 5: out.append((-c, r))
                elif t == 6: out.append((c, -r))
                else: out.append((-c, -r))
            return norm(out)

        def same(a, b):
            sa = set(a)
            return any(set(transform(b, t)) == sa for t in range(8))

        islands = []
        for i in range(m):
            for j in range(n):
                if grid[i][j] and not seen[i][j]:
                    isl = norm(collect(i, j))
                    if not any(same(isl, other) for other in islands):
                        islands.append(isl)
        return len(islands)

