class Solution {
public:
    int numDistinctIslands2(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<bool>> seen(m, vector<bool>(n, false));
        vector<vector<pair<int,int>>> islands;
        int dr[4] = {1,-1,0,0}, dc[4] = {0,0,1,-1};
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (!grid[i][j] || seen[i][j]) continue;
            vector<pair<int,int>> cells;
            stack<pair<int,int>> st;
            st.push({i,j}); seen[i][j] = true;
            while (!st.empty()) {
                auto [r,c] = st.top(); st.pop();
                cells.push_back({r,c});
                for (int d = 0; d < 4; d++) {
                    int nr = r+dr[d], nc = c+dc[d];
                    if (nr>=0 && nr<m && nc>=0 && nc<n && grid[nr][nc] && !seen[nr][nc]) {
                        seen[nr][nc] = true; st.push({nr,nc});
                    }
                }
            }
            auto norm = [](vector<pair<int,int>> v) {
                int mr = INT_MAX, mc = INT_MAX;
                for (auto& p : v) { mr = min(mr,p.first); mc = min(mc,p.second); }
                for (auto& p : v) { p.first -= mr; p.second -= mc; }
                sort(v.begin(), v.end());
                return v;
            };
            auto tf = [&](vector<pair<int,int>> v, int t) {
                for (auto& p : v) {
                    int r = p.first, c = p.second;
                    switch(t){case 1:p={-r,c};break;case 2:p={r,-c};break;case 3:p={-r,-c};break;
                              case 4:p={c,r};break;case 5:p={-c,r};break;case 6:p={c,-r};break;case 7:p={-c,-r};break;}
                }
                return norm(v);
            };
            auto cur = norm(cells);
            bool dup = false;
            for (auto& other : islands) {
                for (int t = 0; t < 8 && !dup; t++)
                    if (tf(other, t) == cur) dup = true;
                if (dup) break;
            }
            if (!dup) islands.push_back(cur);
        }
        return islands.size();
    }
};

