class Solution {
    public int numDistinctIslands2(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] seen = new boolean[m][n];
        List<List<int[]>> islands = new ArrayList<>();
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0 || seen[i][j]) continue;
            List<int[]> cells = new ArrayList<>();
            Deque<int[]> st = new ArrayDeque<>();
            st.push(new int[]{i,j}); seen[i][j] = true;
            while (!st.isEmpty()) {
                int[] top = st.pop(); int r = top[0], c = top[1];
                cells.add(top);
                for (int d = 0; d < 4; d++) {
                    int nr = r+dr[d], nc = c+dc[d];
                    if (nr>=0 && nr<m && nc>=0 && nc<n && grid[nr][nc]==1 && !seen[nr][nc]) {
                        seen[nr][nc] = true; st.push(new int[]{nr,nc});
                    }
                }
            }
            List<int[]> cur = norm(cells);
            boolean dup = false;
            for (List<int[]> other : islands) {
                for (int t = 0; t < 8 && !dup; t++)
                    if (transform(other, t).equals(cur)) dup = true;
                if (dup) break;
            }
            if (!dup) islands.add(cur);
        }
        return islands.size();
    }
    private List<int[]> norm(List<int[]> cells) {
        int mr = Integer.MAX_VALUE, mc = Integer.MAX_VALUE;
        for (int[] p : cells) { mr = Math.min(mr,p[0]); mc = Math.min(mc,p[1]); }
        List<int[]> res = new ArrayList<>();
        for (int[] p : cells) res.add(new int[]{p[0]-mr, p[1]-mc});
        res.sort((a,b)->a[0]!=b[0]?a[0]-b[0]:a[1]-b[1]);
        return res;
    }
    private List<int[]> transform(List<int[]> cells, int t) {
        List<int[]> res = new ArrayList<>();
        for (int[] p : cells) {
            int r = p[0], c = p[1], nr = r, nc = c;
            if (t==1){nr=-r;} else if(t==2){nc=-c;} else if(t==3){nr=-r;nc=-c;}
            else if(t==4){nr=c;nc=r;} else if(t==5){nr=-c;nc=r;}
            else if(t==6){nr=c;nc=-r;} else if(t==7){nr=-c;nc=-r;}
            res.add(new int[]{nr,nc});
        }
        return norm(res);
    }
}

