        m, n = len(grid), len(grid[0])
        seen = [[False]*n for _ in range(m)]
        shapes = set()

        def dfs(sr, sc):
            stack, cells = [(sr, sc)], []
            seen[sr][sc] = True
            while stack:
                r, c = stack.pop()
                cells.append((r, c))
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] and not seen[nr][nc]:
                        seen[nr][nc] = True
                        stack.append((nr, nc))
            return cells

        def canon(cells):
            best = None
            for t in range(8):
                pts = []
                for r, c in cells:
                    if t == 0: pts.append((r, c))
                    elif t == 1: pts.append((-r, c))
                    elif t == 2: pts.append((r, -c))
                    elif t == 3: pts.append((-r, -c))
                    elif t == 4: pts.append((c, r))
                    elif t == 5: pts.append((-c, r))
                    elif t == 6: pts.append((c, -r))
                    else: pts.append((-c, -r))
                pts.sort()
                mr, mc = pts[0]
                s = ';'.join(f"{r-mr},{c-mc}" for r, c in pts)
                best = s if best is None or s < best else best
            return best

        for i in range(m):
            for j in range(n):
                if grid[i][j] and not seen[i][j]:
                    shapes.add(canon(dfs(i, j)))
        return len(shapes)

