class Solution {
    public int numDistinctIslands2(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] seen = new boolean[m][n];
        Set<String> shapes = new HashSet<>();
        int[] dr = {1,-1,0,0}, dc = {0,0,1,-1};
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++) {
            if (grid[i][j] == 0 || seen[i][j]) continue;
            List<int[]> cells = new ArrayList<>();
            Deque<int[]> st = new ArrayDeque<>();
            st.push(new int[]{i,j}); seen[i][j] = true;
            while (!st.isEmpty()) {
                int[] p = st.pop();
                cells.add(p);
                for (int d = 0; d < 4; d++) {
                    int nr = p[0]+dr[d], nc = p[1]+dc[d];
                    if (nr>=0 && nr<m && nc>=0 && nc<n && grid[nr][nc]==1 && !seen[nr][nc]) {
                        seen[nr][nc] = true; st.push(new int[]{nr,nc});
                    }
                }
            }
            String best = null;
            for (int t = 0; t < 8; t++) {
                List<int[]> pts = new ArrayList<>();
                for (int[] q : cells) {
                    int r = q[0], c = q[1];
                    if (t==1){r=-r;} else if(t==2){c=-c;} else if(t==3){r=-r;c=-c;}
                    else if(t==4){int tmp=r;r=c;c=tmp;}
                    else if(t==5){r=-r;int tmp=r;r=c;c=tmp;}
                    else if(t==6){c=-c;int tmp=r;r=c;c=tmp;}
                    else if(t==7){r=-r;c=-c;int tmp=r;r=c;c=tmp;}
                    pts.add(new int[]{r,c});
                }
                pts.sort((a,b)->a[0]!=b[0]?a[0]-b[0]:a[1]-b[1]);
                int mr = pts.get(0)[0], mc = pts.get(0)[1];
                StringBuilder sb = new StringBuilder();
                for (int[] q : pts) sb.append(q[0]-mr).append(',').append(q[1]-mc).append(';');
                String s = sb.toString();
                if (best == null || s.compareTo(best) < 0) best = s;
            }
            shapes.add(best);
        }
        return shapes.size();
    }
}

